    "text": "中文有一整套量詞。一「本」書、一「杯」水、一「張」紙、一「條」麵包。你不會說「一水」，一定要說「一杯水」，因為水本身沒辦法一個一個數。英文其實也有這個概念，它把名詞分成兩類：可以指著數一二三的叫可數名詞，數不出來的叫不可數名詞。book、dog、apple、chair 都是可數名詞；water（水）、rice（米飯）、money（錢）、bread（麵包）都是不可數名詞。"
