    "t": "p",
    "text": "不可數名詞有兩條規定要一起記。第一，前面不能加 a 或 an，寫 a water、a money 都是錯的。第二，後面不能加 s，寫 waters、rices、moneys 也是錯的。道理很單純：它本來就沒有「一個」的概念，自然也就沒有「很多個」這回事。可數名詞剛好相反，前面可以加 a，兩個以上要加 s。"
