    "text": "中文說「一本書」「一台車」「一顆蘋果」，那個「一」不管後面接什麼都長一樣。英文放在名詞前面表示「一個」的字叫做冠詞，有兩種寫法：a 和 an。這兩個意思完全一樣，差別只在唸起來順不順。規則是這樣：後面那個字的第一個聲音如果是母音，也就是 a、e、i、o、u 這五個字母發出來的聲音，就用 an；其他情況一律用 a。原因很單純，a apple 兩個母音黏在一起唸起來會卡住，中間插一個 n 就順了。"
