    "text": "中文要講「我昨天沒去」，只要在動詞前面塞一個「沒」就好，動詞本身完全不動。英文麻煩一點，它得請一個助動詞出來幫忙。現在簡單式用的是 do 和 does,還要看主詞是誰；到了過去，不管主詞是 I、he 還是 they,通通只用一個字：did。這點反而比現在簡單式好記。"
