    "text": "否定句的公式是主詞加 didn't 加動詞。這裡有個非常重要的觀念：過去的意思已經被 did 扛走了，所以後面那個動詞不必再表示過去，要退回最原本的樣子。I didn't went 是台灣學生最常犯的錯，因為腦袋裡想著「這是昨天的事」就手滑把 go 改成 went,但 didn't 裡面已經有過去了，同一句話不需要說兩次。"
