    "text": "疑問句的做法是把 Did 搬到句子最前面，主詞放中間，動詞一樣是最原本的樣子。回答的時候不必把整個動詞再講一次，用 Yes 加主詞加 did,或是 No 加主詞加 didn't 就好。"
