    "text": "否定和疑問完全不用學新的東西，因為前面那個字就是 be 動詞。否定就在 was 或 were 後面加 not,縮成 wasn't、weren't,後面的 V-ing 不動；問句就把 was 或 were 搬到句首。這裡千萬不要跑去找 did 幫忙，句子裡已經有 be 動詞了。"
