    "text": "另外兩種情況也很常見。如果兩件事在同一段時間裡各做各的，兩邊都用過去進行式；如果是一件做完再做下一件，像流水帳一樣按順序排，兩邊都用過去簡單式。判斷的方法還是回到那個問題：你想講的是「當時的畫面」還是「發生過的事」。"
