    "text": "should 用在你覺得這樣做比較好的時候，是建議不是命令。跟 must 比起來語氣軟很多：must 是不做不行，should 是做了會比較好，對方還有選擇的空間。中文的「應該」有時候語氣挺重的，但英文的 should 一直都是軟的，不要拿它去講規定。"
