    "t": "p",
    "text": "第二套是短句，兩三個字就接完話。對方講肯定的，用 So 加助動詞加主詞；對方講否定的，用 Neither 加助動詞加主詞。這裡要注意順序：助動詞要放在主詞前面，跟問句一樣是倒裝的，不是照 So I do 的順序講。"
