    "text": "表格最後一列告訴你一件事：句子裡如果沒有名詞可以講，就只能用 How。「他跑得真快」講的是跑這個動作的方式，用的是副詞，What 那一套接不上去。所以決定用哪一套之前，先想清楚你要讚嘆的到底是一個東西還是一個樣子。"
