    "text": "再看「不一樣」。標準組合是 different from，考試一律以這組為準。similar to 是「相似」，配的是 to 不是 with，這也很常寫錯。這三組沒有規則可推，把 same 配 as、different 配 from、similar 配 to 當成三個整體背下來最快。"
