    "text": "跟使役動詞一樣，感官動詞後面接原形動詞的時候不加 to。I saw him to leave 是錯的，這也是台灣學生很常被扣分的地方。兩組動詞可以一起記：讓別人做事的和用五官感覺到的，後面都不加 to。"
